import { addons } from 'storybook/internal/preview-api';

// src/preview.ts

// src/constants.ts
var ADDON_ID = "storybook/addon-tag-badges";
var EVENTS = {
  REQUEST_CONFIG: `${ADDON_ID}/requestConfig`,
  CONFIG_READY: `${ADDON_ID}/configReady`
};

// src/preview.ts
var preview = {};
var channel = addons.getChannel();
window.tagBadges = window.parent.tagBadges;
channel.emit(EVENTS.REQUEST_CONFIG);
channel.on(EVENTS.CONFIG_READY, () => {
  window.tagBadges = window.parent.tagBadges;
});
var preview_default = preview;

export { preview_default };
